import {products,milkOptions,supportsMilk,itemPrice} from './catalog.js';import {config} from './config.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];const money=n=>`${n.toLocaleString('ru-RU')} ₽`;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const img=n=>`./images/${n}.webp`;
let cart=[];try{cart=JSON.parse(localStorage.getItem('coffee-cart')||'[]');if(!Array.isArray(cart))cart=[]}catch{}cart=cart.filter(x=>products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20);let currentFilter='all',requestId=sessionStorage.getItem('coffee-request-id')||crypto.randomUUID();sessionStorage.setItem('coffee-request-id',requestId);
function renderProducts(){const visible=products.filter(p=>p.available&&(currentFilter==='all'||p.category===currentFilter));$('#products').innerHTML=visible.map(p=>`<article class="product" data-id="${p.id}"><div class="product-img"><img src="${img(p.image)}" alt="Иллюстрация категории: ${esc(p.name)}" loading="lazy">${p.badge?`<span class="badge">${p.badge}</span>`:''}</div><div class="product-title"><h3>${p.name}</h3><strong>${money(p.price)}</strong></div><p>${p.description}</p><div class="product-options">${p.volumes.length?`<select class="volume" aria-label="Объём: ${p.name}">${p.volumes.map(v=>`<option>${v}</option>`).join('')}</select>`:''}${supportsMilk(p)?`<select class="milk" aria-label="Молоко: ${p.name}">${Object.entries(milkOptions).map(([name,cost])=>`<option value="${name}">${name}${cost?' + '+cost+' ₽':''}</option>`).join('')}</select>`:''}</div><button class="add" aria-label="Добавить ${p.name} в корзину">В корзину <span>＋</span></button></article>`).join('')}
function save(){localStorage.setItem('coffee-cart',JSON.stringify(cart));renderCart()}function renderCart(){let count=cart.reduce((a,x)=>a+x.qty,0),total=0;$('#cart-count').textContent=count;$('#checkout-open').disabled=!count;$('#cart-items').innerHTML=cart.length?cart.map((x,i)=>{const p=products.find(y=>y.id===x.id),unit=itemPrice(p,x.milk);total+=unit*x.qty;return `<article class="cart-item"><img src="${img(p.image)}" alt=""><div><h3>${esc(p.name)}</h3><small>${esc([x.volume,x.milk&&x.milk!=='Обычное'?x.milk+' молоко':''].filter(Boolean).join(' / ')||'Без добавок')}</small><small>${money(unit)} / шт.</small><div class="qty"><button data-i="${i}" data-action="minus" aria-label="Уменьшить количество">−</button><span>${x.qty}</span><button data-i="${i}" data-action="plus" aria-label="Увеличить количество">＋</button></div></div><div class="item-cost"><strong>${money(unit*x.qty)}</strong><br><button class="remove" data-i="${i}" data-action="remove">Удалить</button></div></article>`}).join(''):'<div class="empty"><span>✳</span><p>Пока здесь пусто.<br>Самое время выбрать что-то вкусное.</p><a class="text-link" href="#menu" id="empty-menu">Перейти в меню ↗</a></div>';$('#cart-total').textContent=money(total)}
renderProducts();renderCart();let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
$('.filter-row').addEventListener('click',e=>{let b=e.target.closest('.filter');if(!b)return;currentFilter=b.dataset.filter;$$('.filter').forEach(x=>x.classList.toggle('active',x===b));renderProducts()});$('#products').addEventListener('click',e=>{const b=e.target.closest('.add');if(!b)return;const card=b.closest('.product'),p=products.find(x=>x.id===card.dataset.id),volume=card.querySelector('.volume')?.value||'',milk=card.querySelector('.milk')?.value||'';const found=cart.find(x=>x.id===p.id&&x.volume===volume&&x.milk===milk);if(found){if(found.qty>=20){toast('Максимум 20 одинаковых товаров');return}found.qty++}else cart.push({id:p.id,volume,milk,qty:1});save();toast('Добавлено в корзину ✳')});
$('#cart-items').addEventListener('click',e=>{if(e.target.id==='empty-menu'){$('#cart-dialog').close();return}let b=e.target.closest('button[data-action]');if(!b)return;let x=cart[+b.dataset.i];if(b.dataset.action==='plus')x.qty=Math.min(20,x.qty+1);if(b.dataset.action==='minus')x.qty--;if(b.dataset.action==='remove')x.qty=0;cart=cart.filter(i=>i.qty>0);save()});$('#open-cart').onclick=()=>$('#cart-dialog').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());$('#checkout-open').onclick=()=>{if(!cart.length)return;$('#cart-dialog').close();$('#checkout-dialog').showModal()};$('#privacy-open').onclick=()=>$('#privacy-dialog').showModal();$('#privacy-from-form').onclick=()=>$('#privacy-dialog').showModal();$('#menu-toggle').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')};$$('#nav a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Открыть меню')});
$$('[data-config]').forEach(el=>el.textContent=config[el.dataset.config]);document.title=config.name+' — specialty coffee & slow moments';document.querySelector('meta[property="og:title"]').content=config.name+' — specialty coffee';$('#pickup-address').textContent='Самовывоз: '+config.address;if(config.phone){const a=document.createElement('a');a.href='tel:'+config.phone.replace(/[^+\d]/g,'');a.textContent=config.phone;$('#contact-phone').replaceChildren(a)}for(const [label,url] of [['Telegram',config.telegram],['Социальные сети',config.instagram]])if(/^https:\/\//.test(url)){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label+' ↗';$('#social-links').append(a)}
const reviews=[['«Место, где утро становится немного медленнее, а кофе — маленьким событием.»','АННА / ПРИМЕР'],['«Нравится внимание к деталям: от чашки до атмосферы.»','МИХАИЛ / ПРИМЕР'],['«Тот самый повод задержаться ещё на одну чашку.»','ЕЛЕНА / ПРИМЕР']];let reviewIndex=0;function review(){ $('#review-text').textContent=reviews[reviewIndex][0];$('#review-author').textContent=reviews[reviewIndex][1]}$('#review-prev').onclick=()=>{reviewIndex=(reviewIndex+reviews.length-1)%reviews.length;review()};$('#review-next').onclick=()=>{reviewIndex=(reviewIndex+1)%reviews.length;review()};review();
const faq=[['Какой кофе вы используете?','Для концепта предусмотрена подборка specialty-зерна; актуальное происхождение уточняйте в кофейне.'],['Можно ли заказать кофе заранее?','Да, после подключения сервиса заказов можно выбрать желаемое время самовывоза.'],['Есть ли альтернативное молоко?','В демонстрационном меню предусмотрены овсяное, миндальное и кокосовое молоко.'],['Можно ли изменить состав напитка?','Выберите молоко в карточке и оставьте пожелания в комментарии к заказу.'],['Есть ли у вас десерты?','В меню есть выпечка и десерты; ассортимент и наличие демонстрационные.'],['Как оформить заказ?','Добавьте товары в корзину и заполните форму. Работа сервиса зависит от настройки Worker и Telegram.'],['Где находится кофейня?','Адрес уточняется. Он появится здесь после настройки проекта.']];$('#faq-list').innerHTML=faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');$$('.gallery-item').forEach(b=>b.onclick=()=>{$('#lightbox-img').src=img(b.dataset.image);$('#image-dialog').showModal()});
if(config.coordinates&&Array.isArray(config.coordinates)&&config.coordinates.length===2&&config.coordinates.every(Number.isFinite)){const [lon,lat]=config.coordinates;const link=`https://2gis.ru/geo/${lon},${lat}`;$('#map-links').innerHTML=`<a class="text-link" href="${link}" target="_blank" rel="noopener">Открыть в 2GIS ↗</a><a class="text-link" href="https://2gis.ru/directions/points/|${lon},${lat}" target="_blank" rel="noopener">Построить маршрут ↗</a>`;if(config.mapKey){const s=document.createElement('script');s.src='https://mapgl.2gis.com/api/js/v1';s.onload=()=>{try{$('#map').innerHTML='';const map=new mapgl.Map('map',{center:[lon,lat],zoom:16,key:config.mapKey,...(config.mapStyleId?{style:config.mapStyleId}:{})});const marker=new mapgl.Marker(map,{coordinates:[lon,lat]});const el=document.createElement('div');el.className='map-popup';el.append(document.createTextNode(config.name+' — '+config.address));const a=document.createElement('a');a.href=link;a.target='_blank';a.rel='noopener';a.textContent='Маршрут в 2GIS ↗';el.append(a);const popup=new mapgl.HtmlMarker(map,{coordinates:[lon,lat],html:el});el.style.display='none';marker.on('click',()=>el.style.display='block');map.on('click',()=>el.style.display='none')}catch{$('#map').textContent='Не удалось загрузить карту. Откройте адрес в 2GIS.'}};s.onerror=()=>{$('#map').textContent='Не удалось загрузить карту. Откройте адрес в 2GIS.'};document.head.append(s)}else $('.map-fallback small').textContent='Карта появится после добавления ключа 2GIS.'}
$('#checkout-form').addEventListener('submit',async e=>{e.preventDefault();const error=$('#order-error');error.textContent='';const f=new FormData(e.currentTarget),name=String(f.get('name')).trim(),phone=String(f.get('phone')).trim(),time=String(f.get('time')),fulfillment=f.get('fulfillment');if(!cart.length){error.textContent='Корзина пуста.';return}if(name.length<2||!/^\+?[\d\s()\-]{7,25}$/.test(phone)||phone.replace(/\D/g,'').length<10){error.textContent='Укажите имя и корректный номер телефона.';return}if(fulfillment!=='pickup'){error.textContent='Доставка пока демонстрационная. Выберите самовывоз.';return}if(!config.apiUrl){error.textContent='Сервис заказов пока не подключён. Корзина сохранена.';return}const btn=$('#submit-order');btn.disabled=true;btn.textContent='Отправляем…';try{const response=await fetch(config.apiUrl.replace(/\/$/,'')+'/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId,name,phone,time,comment:String(f.get('comment')).trim(),fulfillment,consent:true,items:cart})});const result=await response.json().catch(()=>({}));if(!response.ok||result.ok!==true)throw new Error(result.error||'Не удалось отправить заказ. Попробуйте позже.');cart=[];save();sessionStorage.removeItem('coffee-request-id');requestId=crypto.randomUUID();sessionStorage.setItem('coffee-request-id',requestId);$('#checkout-dialog').close();$('#success-text').textContent='Номер заказа: '+result.orderId;$('#success-dialog').showModal();e.currentTarget.reset()}catch(err){error.textContent=err.message||'Нет связи с сервисом. Корзина сохранена. Повторите запрос с теми же данными или свяжитесь с кофейней.'}finally{btn.disabled=false;btn.innerHTML='Отправить заказ <span>↗</span>'}});
